-- GENERATED by `python -m realy.codegen` from contracts/ — do not edit by hand.

-- Point-in-time correct training set: features exactly as served at decision time + delayed labels.
CREATE OR REPLACE VIEW realy.v_training_dataset AS
-- label_time / label_delay_s say WHEN the label became known: a model trained at time T may only use
-- rows whose label_time <= T (realy train --labels observed applies exactly this cut).
SELECT d.run_id, d.event_id, d.event_time, d.customer_id, d.card_id, d.amount_usd_minor, d.payment_type, d.channel,
       d.outcome, d.score, d.model_version, d.feature_schema_version, d.path, d.rule_ids, d.rule_actions, d.f_cust_count_1h, d.f_cust_count_24h, d.f_cust_amount_sum_24h, d.f_cust_amount_avg_30d, d.f_cust_distinct_countries_24h, d.f_cust_device_novel, d.f_cust_payee_novel, d.f_cust_ip_country_novel, d.f_cust_transfer_count_1h, d.f_cust_transfer_sum_24h, d.f_card_count_1m, d.f_card_count_5m, d.f_card_count_1h, d.f_card_count_24h, d.f_card_amount_sum_1h, d.f_card_amount_sum_24h, d.f_card_amount_max_7d, d.f_card_small_cnp_count_10m, d.f_card_distinct_merchants_10m, d.f_card_distinct_merchants_24h, d.f_card_contactless_count_30m, d.f_card_contactless_sum_30m, d.f_card_atm_count_1h, d.f_card_atm_sum_24h, d.f_card_geo_speed_kmh, d.f_card_secs_since_last, d.f_dev_count_5m, d.f_dev_distinct_cards_1h, d.f_dev_distinct_customers_24h, d.f_ip_count_5m, d.f_ip_distinct_cards_1h, d.f_merch_count_1m, d.f_merch_small_cnp_count_5m, d.f_merch_amount_sum_1h, d.f_term_count_5m, d.f_term_atm_sum_1h, d.f_payee_inbound_count_1h, d.f_payee_inbound_sum_24h, d.f_payee_distinct_senders_24h, d.f_cust_tenure_days, d.f_cust_segment, d.f_cust_avg_ticket_usd, d.f_merch_risk_tier, d.f_merch_fraud_rate_30d, d.f_amount_usd, d.f_is_cnp, d.f_is_contactless, d.f_is_atm, d.f_is_transfer, d.f_is_foreign, d.f_dist_from_home_km, d.f_amount_to_avg_ratio, d.f_local_hour, d.f_credit_utilisation_24h,
       ifNull(l.is_fraud, 0) AS label_is_fraud, ifNull(l.fraud_type, 'NONE') AS label_fraud_type, l.label_time,
       if(l.event_id = 0, NULL, dateDiff('second', d.event_time, l.label_time)) AS label_delay_s, l.source AS label_source
FROM (SELECT * FROM realy.decisions FINAL WHERE revision = 0) AS d
LEFT JOIN (SELECT * FROM realy.labels FINAL) AS l ON l.run_id = d.run_id AND l.event_id = d.event_id;

-- Rule effectiveness against ground truth: fires, precision, share of legitimate traffic hit.
CREATE OR REPLACE VIEW realy.v_rule_performance AS
SELECT d.run_id, rule_id, any(rule_action) AS action, count() AS fires,
       countIf(ifNull(l.is_fraud, 0) = 1) AS fraud_fires, countIf(ifNull(l.is_fraud, 0) = 1) / count() AS precision
FROM (SELECT run_id, event_id, rule_ids, rule_actions FROM realy.decisions FINAL WHERE revision = 0) AS d
ARRAY JOIN d.rule_ids AS rule_id, d.rule_actions AS rule_action
LEFT JOIN (SELECT run_id, event_id, is_fraud FROM realy.labels FINAL) AS l ON l.run_id = d.run_id AND l.event_id = d.event_id
GROUP BY d.run_id, rule_id;

-- Audit completeness: transactions that never received a decision.
CREATE OR REPLACE VIEW realy.v_audit_gaps AS
SELECT e.run_id, e.event_id, e.customer_id, e.event_time_us, e.ingested_at
FROM realy.events_raw AS e
LEFT ANTI JOIN (SELECT DISTINCT run_id, event_id FROM realy.decisions) AS d ON d.run_id = e.run_id AND d.event_id = e.event_id;

-- Per-second latency/throughput from the audit log (independent second measurement).
CREATE OR REPLACE VIEW realy.v_latency_by_second AS
SELECT run_id, toStartOfSecond(decided_at) AS second, count() AS decisions,
       quantileExact(0.5)(hot_path_us) / 1000 AS hot_p50_ms, quantileExact(0.99)(hot_path_us) / 1000 AS hot_p99_ms,
       quantileExact(0.99)(lat_feature_lookup_us) / 1000 AS feature_p99_ms, quantileExact(0.99)(lat_model_call_us) / 1000 AS model_p99_ms,
       quantileExact(0.99)(lat_audit_append_us) / 1000 AS audit_append_p99_ms,
       quantileExact(0.99)(dateDiff('microsecond', decided_at, ingested_at)) / 1000 AS audit_visibility_p99_ms,
       countIf(degraded = 1) AS degraded, countIf(outcome = 'DECLINE') AS declines
FROM realy.decisions GROUP BY run_id, second;
